int bx_ntvdm_bop_dem_ch_mod_v2(bx_ntvdm_dem_whole_provider_v1*p,const bx_ntvdm_exception_event_v1*b,const bx_ntvdm_cpu_state_v1*c,uint8_t drive,const wchar_t*path,int startup,bx_ntvdm_cpu_result_v2*r){DWORD dwAttr,error=0;int admitted;if(!p||!b||!c||!path||!r)return 0;/* Original GetVDMAddr is replaced by checked gathered path. */if((c->eax&0xffu)==0u){if(startup)return get_finish(b,r,0);if(!bx_ntvdm_host_namespace_v1_query_file_attributes(p->host_namespace,drive,path,&dwAttr,&error))return demClientError(b,r,error);if(dwAttr==FILE_ATTRIBUTE_NORMAL)dwAttr=0;else dwAttr&=DOS_ATTR_MASK;return get_finish(b,r,(uint16_t)dwAttr);}admitted=bx_ntvdm_dem_file_view_v1_admit(&p->file_view,BX_NTVDM_MUTATION_CLASS_V1_FILE_METADATA);if(startup||admitted!=BX_NTVDM_DEM_FILE_VIEW_V1_OK)return demClientError(b,r,ERROR_ACCESS_DENIED);dwAttr=(uint16_t)c->ecx;if(dwAttr==0)dwAttr=FILE_ATTRIBUTE_NORMAL;dwAttr&=DOS_ATTR_MASK;if(!bx_ntvdm_host_namespace_v1_set_file_attributes(p->host_namespace,drive,path,dwAttr,&error))return demClientError(b,r,error);return finish(b,r,0);}